/* All prices and returns are fictional game parameters, not market quotations. */
(function(root){
const MONTH=720,BANKS=['Raiffeisen','Sparkasse','Volksbank','Bank Austria','N26','Revolut'];
const JOBS=[{name:'Aushilfe',pay:1550,cost:0,xp:0},{name:'Sachbearbeitung',pay:2400,cost:120,xp:15},{name:'Softwareentwicklung',pay:3900,cost:650,xp:90},{name:'Projektleitung',pay:5400,cost:1500,xp:240},{name:'Geschäftsführung',pay:8500,cost:5000,xp:600}];
const ASSETS=[
['garage','Immobilien','Einzelgarage','▥',24000,95,'Vermieteter Stellplatz · laufende Kosten abgezogen.'],['flat','Immobilien','Stadtwohnung','▤',185000,620,'Kleine Wohnung · Nettomiete nach Rücklage.'],['house','Immobilien','Mehrfamilienhaus','▦',950000,3400,'Sechs Einheiten · Verwaltung berücksichtigt.'],
['coffee','Unternehmen','Kaffeebar','☕',22000,650,'Personal, Miete und Einkauf bereits abgezogen.'],['agency','Unternehmen','Digitalagentur','◈',85000,2400,'Kleines Team · Ertrag schwankt mit der Konjunktur.'],['hotel','Unternehmen','Boutiquehotel','♜',1800000,22000,'20 Zimmer · saisonaler Nettoertrag.'],
['watch','Sammlerstücke','Mechanische Uhr','◷',6500,0,'Sammlerwert · kein laufendes Einkommen.'],['art','Sammlerstücke','Zeitgenössische Kunst','▧',28000,0,'Ein Sammlerstück mit unsicherem Wiederverkaufswert.'],['classic','Autos','Klassischer Roadster','♧',48000,-95,'Versicherung und Wartung: 95 € pro Monat.'],['electric','Autos','Elektro-Limousine','ϟ',42000,-75,'Privatfahrzeug · laufende Kosten 75 € pro Monat.'],
['marina','Schiffe','Charter-Segelyacht','⛵',175000,900,'Chartergewinn nach Liegeplatz und Instandhaltung.'],['ship','Schiffe','Kleines Frachtschiff','◒',6200000,42000,'Logistikbetrieb · Treibstoff und Crew eingerechnet.'],['airfield','Flughäfen','Regionalflugplatz','✈',12500000,68000,'Landerechte, Hangars und Betriebskosten.'],['airport','Flughäfen','Regionalflughafen','✈',85000000,390000,'Passagierbetrieb mit umfangreicher Infrastruktur.'],['island','Inseln','Private Naturinsel','⌁',3900000,-4500,'Privater Rückzugsort · Unterhalt 4.500 € monatlich.'],['resort','Inseln','Inselresort','☀',24000000,145000,'Tourismusbetrieb · Nettogewinn nach Unterhalt.']
].map(([id,category,name,icon,price,income,description])=>({id,category,name,icon,price,income,description}));
const STOCKS=[{id:'world',name:'Weltmarkt-Fonds',symbol:'WELT',base:105,risk:.025},{id:'alpine',name:'Alpine Energie',symbol:'ALPE',base:48,risk:.06},{id:'nova',name:'Nova Technologie',symbol:'NOVA',base:185,risk:.1},{id:'urban',name:'Urban Infrastruktur',symbol:'URBN',base:72,risk:.045}];
function fresh(){return {version:1,cash:2500,bank:'Raiffeisen',job:-1,xp:0,owned:{},shares:{},prices:Object.fromEntries(STOCKS.map(s=>[s.id,s.base])),loans:[],elapsed:0,last:Date.now(),marketAt:0,history:[2500],events:[{text:'Startkapital erhalten',amount:2500}],held:0};}
function valid(s){return s&&s.version===1&&Number.isFinite(s.cash)&&s.cash>=0&&BANKS.includes(s.bank)&&Number.isInteger(s.job)&&s.job>=-1&&s.job<JOBS.length&&Number.isFinite(s.elapsed)&&s.elapsed>=0&&Number.isFinite(s.last)&&s.last>0&&Number.isFinite(s.xp)&&s.xp>=0&&s.owned&&s.shares&&s.prices&&ASSETS.every(a=>Number.isInteger(s.owned[a.id]||0)&&(s.owned[a.id]||0)>=0)&&STOCKS.every(a=>Number.isFinite(s.prices[a.id])&&s.prices[a.id]>0&&Number.isInteger(s.shares[a.id]||0)&&(s.shares[a.id]||0)>=0)&&Array.isArray(s.loans)&&s.loans.every(l=>Number.isFinite(l.balance)&&l.balance>=0&&Number.isFinite(l.payment)&&l.payment>=0&&l.months>0)&&Array.isArray(s.events)&&Array.isArray(s.history)&&s.history.every(Number.isFinite);}
function passive(s){return ASSETS.reduce((n,a)=>n+(s.owned[a.id]||0)*a.income,0);}
function salary(s){return s.job>=0?JOBS[s.job].pay:0;}
function debt(s){return s.loans.reduce((n,l)=>n+l.balance,0);}
function net(s){return s.cash+ASSETS.reduce((n,a)=>n+(s.owned[a.id]||0)*a.price*.9,0)+STOCKS.reduce((n,a)=>n+(s.shares[a.id]||0)*s.prices[a.id],0)-debt(s);}
function log(s,text,amount=0){s.events.unshift({text,amount});s.events=s.events.slice(0,20);}
function tick(s,seconds,holding=false,random=Math.random){seconds=Math.max(0,Math.min(seconds,MONTH));const before=s.elapsed;s.elapsed+=seconds;s.xp+=holding?seconds/10:0;let earned=holding?seconds*(.2+Math.max(0,s.job)*.08):0;s.held+=holding?seconds:0;let income=(salary(s)+passive(s))*seconds/MONTH;let rates=0;for(let l of s.loans){let dt=seconds/MONTH;let interest=l.balance*.065/12*dt;let due=Math.min(l.balance+interest,l.payment*dt);l.balance+=interest;const available=Math.max(0,s.cash+income+earned-rates);let paid=Math.min(available,due);l.balance-=paid;rates+=paid;l.months=Math.max(.0001,l.months-dt);}s.loans=s.loans.filter(l=>l.balance>.01);s.cash=Math.max(0,s.cash+income+earned-rates);if(Math.floor(s.elapsed/30)>Math.floor(before/30)){for(let a of STOCKS)s.prices[a.id]=Math.max(a.base*.15,Math.min(a.base*8,s.prices[a.id]*(1+(random()-.5)*a.risk)));s.history.push(net(s));s.history=s.history.slice(-24);}s.last=Date.now();return earned;}
function buy(s,id,finance=false){let a=ASSETS.find(a=>a.id===id);if(!a)return 'Unbekannter Besitz.';let down=finance?a.price*.3:a.price;if(s.cash<down)return 'Dafür reicht dein Guthaben noch nicht.';if(finance){let p=a.price*.7;if(p>limit(s)-debt(s))return 'Dein Kreditrahmen reicht dafür noch nicht.';let error=loan(s,p,60,a.name);if(error)return error;}s.cash-=a.price;s.owned[id]=(s.owned[id]||0)+1;log(s,a.name+' gekauft',-down);return '';}
function sell(s,id){let a=ASSETS.find(a=>a.id===id);if(!a||!s.owned[id])return 'Du besitzt dieses Objekt noch nicht.';s.owned[id]--;s.cash+=a.price*.9;log(s,a.name+' verkauft',a.price*.9);return '';}
function limit(s){return Math.max(0,(salary(s)+Math.max(0,passive(s)))*18+ASSETS.reduce((n,a)=>n+(s.owned[a.id]||0)*a.price*.45,0));}
function loan(s,p,months=36,purpose='Privatkredit'){if(!Number.isFinite(p)||p<100||p>limit(s)-debt(s))return 'Betrag liegt außerhalb deines Kreditrahmens.';let r=.065/12;let payment=p*r/(1-Math.pow(1+r,-months));if(payment+s.loans.reduce((n,l)=>n+l.payment,0)>(salary(s)+Math.max(0,passive(s)))*.4)return 'Die Raten würden 40 % deines Monatseinkommens überschreiten.';s.loans.push({balance:p,payment,months,purpose});s.cash+=p;log(s,purpose+' aufgenommen',p);return '';}
function apply(s,i){let j=JOBS[i];if(!j||i<=s.job)return 'Wähle einen höheren Job.';if(s.xp<j.xp)return 'Sammle zuerst mehr Erfahrung beim Gedrückthalten.';if(s.cash<j.cost)return 'Die Weiterbildung ist noch zu teuer.';s.cash-=j.cost;s.job=i;log(s,'Neue Stelle: '+j.name,-j.cost);return '';}
function trade(s,id,qty){let a=STOCKS.find(x=>x.id===id);if(!a||!Number.isInteger(qty)||!qty)return 'Ungültige Stückzahl.';let cost=s.prices[id]*Math.abs(qty),fee=cost*.005;if(qty>0){if(cost+fee>s.cash)return 'Guthaben reicht inklusive 0,5 % Gebühr nicht aus.';s.cash-=cost+fee;}else{if((s.shares[id]||0)<-qty)return 'Du besitzt nicht genug Anteile.';s.cash+=cost-fee;}s.shares[id]=(s.shares[id]||0)+qty;log(s,a.name+(qty>0?' gekauft':' verkauft'),qty>0?-cost-fee:cost-fee);return '';}
root.Game={MONTH,BANKS,JOBS,ASSETS,STOCKS,fresh,valid,passive,salary,debt,net,tick,buy,sell,limit,loan,apply,trade,log};
})(typeof module!=='undefined'?module.exports:window);
